import React, { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Loader2, FileText, File as FileIcon, CheckCircle2, XCircle, X, Database, Wand2, AlertCircle, ShieldCheck, ArrowLeft } from 'lucide-react';
import { cn } from "@/lib/utils";
import { SimpleTooltip } from "@/components/ui/tooltip";
import sitePackageService from '@/modules/site-packages/services/sitePackageService';

const ethicsBoards = [
  {
    name: "Provincial Application",
    documents: [
      { name: "Completed PIA Form", requirement: "Mandatory" },
      { name: "Study Protocol", requirement: "Mandatory" },
      { name: "Investigators Brochure", requirement: "Mandatory" },
      { name: "OCREB approved Consent Forms", requirement: "Mandatory" },
      { name: "Participant Materials", requirement: "Mandatory" },
      { name: "Principal Investigators CV and other information", requirement: "Mandatory" },
      { name: "Conflict of Interest Declarations", requirement: "If applicable" },
      { name: "Data Safety Monitoring Plan", requirement: "Mandatory" },
      { name: "Recruitment Procedures", requirement: "If applicable" },
      { name: "PIA Form Signature", requirement: "Mandatory" }
    ]
  },
  {
    name: "UHN REB (Princess Margaret Cancer Centre)",
    documents: [
      { name: "REB Application Form", requirement: "Mandatory" },
      { name: "Protocol", requirement: "Mandatory" },
      { name: "Informed Consent form", requirement: "Mandatory" },
      { name: "Investigators Brochure/ Product Monograph", requirement: "Mandatory" },
      { name: "Study Budget/ Clinical trial Agreement(CTA)", requirement: "Mandatory" },
      { name: "Safety Monitoring Plan", requirement: "Mandatory" },
      { name: "Regulatory approvals", requirement: "Mandatory" },
      { name: "Data management plan", requirement: "Mandatory" },
      { name: "Principal Investigators CV and other information", requirement: "Mandatory" },
      { name: "Conflict of Interest Declarations", requirement: "If applicable" },
      { name: "Recruitment materials", requirement: "If applicable" }
    ]
  },
  {
    name: "ADVARRA IRB",
    documents: [
      { name: "Protocol", requirement: "Mandatory" },
      { name: "Informed Consent form", requirement: "Mandatory" },
      { name: "Investigators Brochure/ Product Monograph", requirement: "Mandatory" },
      { name: "Study Budget/ Clinical trial Agreement(CTA)", requirement: "Mandatory" },
      { name: "Safety Monitoring Plan", requirement: "Mandatory" },
      { name: "Regulatory approvals", requirement: "Mandatory" },
      { name: "Data management plan", requirement: "Mandatory" },
      { name: "Principal Investigators CV and other information", requirement: "Mandatory" },
      { name: "Conflict of Interest Declarations", requirement: "Mandatory" },
      { name: "Recruitment materials", requirement: "Mandatory" }
    ]
  },
  {
    name: "WCG IRB (WIRB-Copernicus Group)",
    documents: [
      { name: "Protocol", requirement: "Mandatory" },
      { name: "Informed Consent form", requirement: "Mandatory" },
      { name: "Investigators Brochure/ Product Monograph", requirement: "Mandatory" },
      { name: "Study Budget/ Clinical trial Agreement(CTA)", requirement: "Mandatory" },
      { name: "Safety Monitoring Plan", requirement: "Mandatory" },
      { name: "Regulatory approvals", requirement: "Mandatory" },
      { name: "Data management plan", requirement: "Mandatory" },
      { name: "Principal Investigators CV and other information", requirement: "Mandatory" },
      { name: "Conflict of Interest Declarations", requirement: "Mandatory" },
      { name: "Recruitment materials", requirement: "Mandatory" }
    ]
  }
];

const getFileIcon = (file) => {
  if (!file) return <FileIcon className="w-5 h-5 text-muted-foreground" />;
  const ext = file.name.split('.').pop().toLowerCase();
  if (ext === 'pdf') return <FileText className="w-5 h-5 text-red-500" />;
  if (ext === 'docx') return <FileText className="w-5 h-5 text-blue-500" />;
  return <FileIcon className="w-5 h-5 text-muted-foreground" />;
};

const getRequirementBadge = (requirement) => {
  if (requirement === "Mandatory") {
    return <Badge className="bg-amber-500 text-white font-semibold">Required</Badge>;
  }
  return <Badge variant="secondary" className="font-semibold">{requirement}</Badge>;
};

const SitePackagePage = ({ onBack, studyId, siteId, packageName: defaultPackageName = 'Site Package' }) => {
  const [uploadedDocs, setUploadedDocs] = useState({});
  const [uploadProgress, setUploadProgress] = useState({});
  const [uploadErrors, setUploadErrors] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState("");
  const [submitSuccess, setSubmitSuccess] = useState(false);
  const [selectedBoard, setSelectedBoard] = useState(0);
  const [draggedOver, setDraggedOver] = useState(null);
  const packageName = defaultPackageName;

  const simulateUpload = (docName, file) => {
    setUploadProgress(prev => ({ ...prev, [docName]: 0 }));
    let progress = 0;
    const interval = setInterval(() => {
      progress += Math.floor(Math.random() * 20) + 10;
      if (progress >= 100) {
        progress = 100;
        clearInterval(interval);
        setUploadProgress(prev => ({ ...prev, [docName]: 100 }));
        setUploadedDocs(prev => ({ ...prev, [docName]: file }));
      } else {
        setUploadProgress(prev => ({ ...prev, [docName]: progress }));
      }
    }, 150);
  };

  const handleRemoveFile = (docName) => {
    setUploadedDocs(prev => {
      const newDocs = { ...prev };
      delete newDocs[docName];
      return newDocs;
    });
    setUploadProgress(prev => {
      const newProg = { ...prev };
      delete newProg[docName];
      return newProg;
    });
    setUploadErrors(prev => {
      const newErrs = { ...prev };
      delete newErrs[docName];
      return newErrs;
    });
  };

  const handleDragOver = (e, docName) => {
    e.preventDefault();
    e.stopPropagation();
    setDraggedOver(docName);
  };

  const handleDragLeave = (e, docName) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.currentTarget === e.target) {
      setDraggedOver(null);
    }
  };

  const handleDrop = (e, docName) => {
    e.preventDefault();
    e.stopPropagation();
    setDraggedOver(null);

    const file = e.dataTransfer.files[0];
    if (!file) return;

    const allowedTypes = ["application/pdf", "application/vnd.openxmlformats-officedocument.wordprocessingml.document"];
    if (!allowedTypes.includes(file.type)) {
      setUploadErrors(prev => ({ ...prev, [docName]: "Only PDF or DOCX files are allowed." }));
      return;
    }

    setUploadErrors(prev => ({ ...prev, [docName]: undefined }));
    setUploadedDocs(prev => ({ ...prev, [docName]: undefined }));
    simulateUpload(docName, file);
  };

  const handleUploadMethod = (docName, method) => {
    console.log(`${method} selected for ${docName}`);
    alert(`${method === 'import' ? 'Import from TMF' : 'AI Generate'} functionality coming soon for: ${docName}`);
  };

  const currentBoard = ethicsBoards[selectedBoard];
  const allMandatoryUploaded = currentBoard.documents
    .filter(doc => doc.requirement === "Mandatory")
    .every(doc => uploadedDocs[doc.name]);

  const handleSubmit = async () => {
    console.log('🟦 [SitePackagePage] handleSubmit called');
    setIsSubmitting(true);
    setSubmitError("");
    setSubmitSuccess(false);

    try {
      console.log('🔄 [SitePackagePage] Starting package creation...');

      if (!studyId || !siteId) {
        setSubmitError('Study and site are required to create a site package.');
        return;
      }

      const payload = {
        study: studyId,
        site: siteId,
        ethicsBoard: ethicsBoards[selectedBoard]?.name || "",
        packageName,
        description: "",
        priority: "Medium",
        contactPerson: {},
        notes: "",
        documents: []
      };

      const createResp = await sitePackageService.createSitePackage(payload);
      const created = createResp?.data?.sitePackage || createResp?.sitePackage || createResp?.data;
      const packageId = created?._id;
      if (!packageId) {
        throw new Error('Failed to create site package: No package ID returned');
      }

      // Upload each document
      const entries = Object.entries(uploadedDocs).filter(([, file]) => !!file);
      for (const [docName, file] of entries) {
        await sitePackageService.uploadSitePackageDocument(
          packageId,
          docName,
          file,
          { studyId, siteId },
          undefined,
          undefined,
          'upload',
          (pct) => setUploadProgress(prev => ({ ...prev, [docName]: pct })),
        );
      }

      setSubmitSuccess(true);
      if (typeof onBack === 'function') {
        onBack();
      }
    } catch (error) {
      console.error('❌ [SitePackagePage] Error submitting package:', error);
      const data = error?.response?.data;
      let msg = error.message || 'Failed to submit package';
      if (typeof data?.error === 'string') msg = data.error;
      else if (typeof data?.detail === 'string') msg = data.detail;
      else if (Array.isArray(data?.detail)) {
        msg = data.detail.map((x) => (typeof x === 'string' ? x : x?.msg || JSON.stringify(x))).join(', ');
      }
      setSubmitError(msg);
    } finally {
      setIsSubmitting(false);
    }
  };

  const renderDocumentsCards = (board) => {
    const uploadedCount = Object.values(uploadedDocs).filter(Boolean).length;
    const mandatoryDocs = board.documents.filter(d => d.requirement === 'Mandatory');
    const mandatoryUploadedCount = mandatoryDocs.filter(d => uploadedDocs[d.name]).length;

    return (
      <div className="space-y-5">
        <div className="p-5 bg-gradient-to-r from-slate-700 to-slate-600 rounded-lg text-white shadow-lg">
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-3">
              <div className="w-12 h-12 rounded-lg bg-white/20 backdrop-blur-sm flex items-center justify-center">
                <FileText className="w-6 h-6" />
              </div>
              <div>
                <p className="text-lg font-bold">
                  {uploadedCount} of {board.documents.length} Documents Uploaded
                </p>
                <p className="text-sm opacity-90">
                  Required: {mandatoryUploadedCount}/{mandatoryDocs.length}
                  {allMandatoryUploaded && <span className="ml-2 font-semibold">✓ All Complete</span>}
                </p>
              </div>
            </div>
          </div>

          <div className="flex flex-wrap gap-2">
            {board.documents.map((doc, idx) => (
              <SimpleTooltip key={doc.name} content={doc.name}>
                <div
                  className={cn(
                    "w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold transition-all",
                    uploadedDocs[doc.name]
                      ? "bg-emerald-500 text-white scale-110 shadow-lg"
                      : doc.requirement === 'Mandatory'
                        ? "bg-white/30 text-white border-2 border-white/60"
                        : "bg-white/10 text-white/60"
                  )}
                >
                  {uploadedDocs[doc.name] ? "✓" : idx + 1}
                </div>
              </SimpleTooltip>
            ))}
          </div>
        </div>

        <div className="flex flex-col gap-3">
          {board.documents.map((doc, index) => {
            const hasFile = uploadedDocs[doc.name];
            const hasError = uploadErrors[doc.name];
            const isUploading = uploadProgress[doc.name] > 0 && uploadProgress[doc.name] < 100;
            const isRequired = doc.requirement === 'Mandatory';

            return (
              <div
                key={doc.name}
                onDragOver={(e) => handleDragOver(e, doc.name)}
                onDragLeave={(e) => handleDragLeave(e, doc.name)}
                onDrop={(e) => handleDrop(e, doc.name)}
                className={cn(
                  "border rounded-lg p-4 space-y-3 transition-all",
                  draggedOver === doc.name && "border-slate-700 bg-slate-100 shadow-xl scale-[1.02]",
                  hasFile && !hasError && "border-emerald-300 bg-emerald-50/30",
                  hasError && "border-red-300 bg-red-50/30",
                  !hasFile && !hasError && draggedOver !== doc.name && "border-slate-200 hover:border-slate-300 hover:shadow-md"
                )}
              >
                <div className="flex items-center gap-3 text-xs sm:text-sm">
                  <div
                    className={cn(
                      "w-7 h-7 rounded-md flex items-center justify-center flex-shrink-0 text-[11px] font-semibold shadow-sm transition-all",
                      hasFile ? "bg-emerald-600 text-white" : isRequired ? "bg-amber-500 text-white" : "bg-slate-400 text-white"
                    )}
                  >
                    {hasFile ? <CheckCircle2 className="w-4 h-4" /> : index + 1}
                  </div>

                  <div className="flex-1 min-w-0 space-y-0.5">
                    <div className="flex items-center gap-2">
                      <SimpleTooltip content={doc.name}>
                        <span className="font-medium text-slate-900 truncate">
                          {doc.name}
                        </span>
                      </SimpleTooltip>
                      {getRequirementBadge(doc.requirement)}
                    </div>

                    <div className="flex items-center gap-2 text-[11px] text-slate-500">
                      {hasFile ? (
                        <>
                          <span className="truncate">
                            {uploadedDocs[doc.name].name}
                          </span>
                          <span className="whitespace-nowrap">
                            · {(uploadedDocs[doc.name].size / 1024).toFixed(1)} KB
                          </span>
                        </>
                      ) : (
                        <span className="italic text-slate-400">No file uploaded</span>
                      )}
                    </div>

                    {isUploading && (
                      <div className="flex items-center gap-2 mt-0.5">
                        <div className="flex-1 h-1.5 bg-slate-200 rounded-full overflow-hidden">
                          <div
                            className="h-full bg-slate-700 transition-all duration-300"
                            style={{ width: `${uploadProgress[doc.name]}%` }}
                          />
                        </div>
                        <span className="text-[11px] text-slate-500 font-medium">
                          {uploadProgress[doc.name]}%
                        </span>
                      </div>
                    )}

                    {hasError && (
                      <div className="text-[11px] text-red-600 mt-0.5">
                        {uploadErrors[doc.name]}
                      </div>
                    )}
                  </div>

                  <div className="flex items-center gap-2">
                    {!hasFile && (
                      <>
                        <Button
                          type="button"
                          variant="ghost"
                          size="icon"
                          className="h-7 w-7 text-slate-400 hover:text-slate-700"
                          onClick={() => handleUploadMethod(doc.name, 'import')}
                          disabled={isSubmitting || isUploading}
                        >
                          <Database className="w-3 h-3" />
                        </Button>
                        <Button
                          type="button"
                          variant="ghost"
                          size="icon"
                          className="h-7 w-7 text-slate-400 hover:text-slate-700"
                          onClick={() => handleUploadMethod(doc.name, 'generate')}
                          disabled={isSubmitting || isUploading}
                        >
                          <Wand2 className="w-3 h-3" />
                        </Button>
                      </>
                    )}

                    {hasFile && (
                      <Button
                        type="button"
                        variant="ghost"
                        size="icon"
                        onClick={() => handleRemoveFile(doc.name)}
                        className="h-7 w-7 text-slate-400 hover:text-red-600 hover:bg-red-50"
                        disabled={isSubmitting}
                      >
                        <X className="w-3 h-3" />
                      </Button>
                    )}
                  </div>
                </div>

              </div>
            );
          })}
        </div>
      </div>
    );
  };

  return (
    <div className="max-w-7xl mx-auto space-y-8 px-4 sm:px-6 lg:px-8 py-8">
      <Card className="border-none shadow-lg">
        <CardHeader className="pb-4">
          <div className="flex items-center gap-4 mb-3">
            {onBack && (
              <Button
                variant="ghost"
                size="sm"
                onClick={onBack}
                className="gap-2"
              >
                <ArrowLeft className="w-4 h-4" />
                Back to List
              </Button>
            )}
          </div>
          <CardTitle className="text-xl sm:text-2xl font-bold text-slate-900">
            Site Package: Ethics Board Requirements
          </CardTitle>
          <CardDescription className="text-sm sm:text-base text-slate-600">
            Upload and manage required documents for ethics board submissions.
          </CardDescription>
        </CardHeader>

        <CardContent>
          <Tabs
            value={selectedBoard.toString()}
            onValueChange={(value) => setSelectedBoard(parseInt(value))}
          >
            <TabsList className="grid w-full grid-cols-1 sm:grid-cols-2 lg:grid-cols-4">
              <TabsTrigger value="0">Provincial Application</TabsTrigger>
              <TabsTrigger value="1">UHN REB</TabsTrigger>
              <TabsTrigger value="2">ADVARRA IRB</TabsTrigger>
              <TabsTrigger value="3">WCG IRB (WIRB-Copernicus Group)</TabsTrigger>
            </TabsList>

            {ethicsBoards.map((board, index) => (
              <TabsContent
                key={index}
                value={index.toString()}
                className="mt-6"
              >
                <div className="mb-5">
                  <h3 className="text-lg font-semibold text-slate-900 mb-2">{board.name}</h3>
                  <p className="text-sm text-slate-600">
                    Upload the required documents for {board.name} submission.
                  </p>
                </div>
                {renderDocumentsCards(board)}
              </TabsContent>
            ))}
          </Tabs>

          <div className="mt-8 p-5 bg-slate-50 rounded-lg border-2 border-slate-200">
            <div className="flex flex-col sm:flex-row gap-4 items-center justify-between">
              <div className="flex-1">
                <h4 className="text-sm font-semibold text-slate-900 mb-1">Ready to submit?</h4>
                <p className="text-xs text-slate-600">
                  {allMandatoryUploaded
                    ? "All required documents have been uploaded."
                    : `Please upload all required documents before submitting. (${currentBoard.documents.filter(d => d.requirement === 'Mandatory' && !uploadedDocs[d.name]).length} remaining)`}
                </p>
              </div>

              <Button
                onClick={handleSubmit}
                disabled={isSubmitting || !allMandatoryUploaded}
                size="lg"
                className="h-11 px-6 gap-2 font-semibold"
              >
                {isSubmitting ? (
                  <>
                    <Loader2 className="w-4 h-4 animate-spin" />
                    Submitting...
                  </>
                ) : (
                  <>
                    <CheckCircle2 className="w-4 h-4" />
                    Submit Package
                  </>
                )}
              </Button>
            </div>

            {submitError && (
              <div className="mt-4 p-3 bg-red-50 border-2 border-red-200 rounded-lg flex items-start gap-2">
                <AlertCircle className="w-5 h-5 text-red-600 flex-shrink-0" />
                <p className="text-sm text-red-700 font-medium">{submitError}</p>
              </div>
            )}

            {submitSuccess && (
              <div className="mt-4 p-3 bg-emerald-50 border-2 border-emerald-200 rounded-lg flex items-start gap-2">
                <CheckCircle2 className="w-5 h-5 text-emerald-600 flex-shrink-0" />
                <p className="text-sm text-emerald-700 font-medium">
                  Package submitted successfully!
                </p>
              </div>
            )}
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

export default SitePackagePage;

